onMounted(()=>{try{scene=new THREE.Scene();scene.background=new THREE.Color('#09151d');scene.fog=new THREE.Fog('#09151d',65,110);camera=new THREE.PerspectiveCamera(42,1,.1,200);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.value.appendChild(renderer.domElement);scene.add(new THREE.AmbientLight(0xd6efff,2));const sun=new THREE.DirectionalLight(0xffffff,3);sun.position.set(12,30,20);scene.add(sun);const floor=new THREE.GridHelper(60,30,0x28404b,0x142b36);floor.position.y=-.05;scene.add(floor);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.maxPolarAngle=Math.PI/2.05;controls.minDistance=8;controls.maxDistance=85;reset();renderer.domElement.addEventListener('click',pick);observer=new ResizeObserver(()=>{const {width,height}=host.value.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix()});observer.observe(host.value);draw();const tick=()=>{frame=requestAnimationFrame(tick);controls.update();renderer.render(scene,camera)};tick()}catch(err){fallback.value=true;error.value='WebGL unavailable in this browser. Showing an interactive 2D field instead.'}})
onBeforeUnmount(()=>{stop();cancelAnimationFrame(frame);observer?.disconnect();controls?.dispose();disposeGroup();scene?.traverse(o=>{o.geometry?.dispose();o.material?.dispose()});renderer?.dispose()})
</script>
<template>
 <div class="shell">
  <header><a class="brand" href="#"><span class="mark">T</span><span>TERRAFLUX<small>PHYSICS OBSERVATORY</small></span></a><span class="status"><i></i> LOCAL WORKSPACE</span><label class="upload">↥ Open JSON<input type="file" accept=".json,application/json" @change="upload"></label></header>
  <main><aside><div class="eyebrow">EXPERIMENT / 001</div><h1>Weather,<br>in perspective.</h1><p class="intro">Explore the fields behind the physics. Inspect temperature, wind and accumulated rainfall on a shared grid.</p>
   <section><div class="section-label">01 / FIELD LAYERS</div><button v-for="[key,title,description] in [['temperature','Air temperature','Dry transport · °C'],['wind','Wind speed','Prescribed field · m/s'],['rainfall','Rainfall accumulation','Observation-derived · mm'],['terrain','Terrain elevation','Surface geometry · m'],['slope','Terrain slope','Inclination · degrees'],['aspect','Downhill aspect','Bearing from north · degrees'],['water','Surface water depth','Closed-domain routing · mm'],['soil','Soil water storage','Infiltrated water · mm'],['cloud','Cloud cover','Synthetic fraction · %'],['pressure','Sea-level pressure','Synthetic regional field · hPa'],['humidity','Relative humidity','Synthetic regional field · %'],['density','Air density','Coupled moist layer · kg/m³'],['moisture','Specific humidity','Coupled moist layer · g/kg'],['cape','Convective energy (CAPE)','Surface-parcel column · J/kg'],['cloudbase','Cloud base (LCL)','Surface-parcel column · m'],['cloudtop','Equilibrium level','Surface-parcel column · m'],['clouds','Cloud formation','Fronts + convection · type'],['precip','Precipitation rate','Cloud outcomes · mm/h'],['accum','Interval accumulation','Cloud outcomes · mm'],['stormwind','Storm wind field','Tropical cyclones · m/s'],['mpi','Potential intensity','Ocean energy bound · m/s'],['gpi','Genesis potential','Emanuel–Nolan index'],['surge','Storm surge','Coastal cells · m'],['stp','Tornado parameter','Significant tornado parameter'],['helicity','Storm-relative helicity','0–1 km · m²/s²'],['lifting','Orographic lifting','V·∇h · m/s (− = descent)'],['blocked','Blocked fraction','Froude blocking · 0–1'],['foehn','Foehn warming','Lee anomaly · K'],['coldpool','Cold-air pool','Valley deficit · K'],['oroprecip','Orographic precipitation','Windward condensation · mm/h'],['valley','Valley depth','Below surroundings · m'],['discharge','River discharge','Catchment routing · m³/s'],['surfacewater','Surface / flood water','Overland + floodplain · mm'],['saturation','Soil saturation','Regolith store · 0–1'],['watertable','Water-table depth','Unconfined aquifer · m'],['snowpack','Snowpack','Water equivalent · mm'],['erosion','Erosion','Cumulative stream power · mm'],['deposition','Deposition','Cumulative sediment · mm'],['stability','Slope factor of safety','Infinite slope · FS'],['floodclass','Flood hazard class','0 none → 4 extreme']]" :key="key" class="layer" :class="{active:layer===key}" :disabled="(['lifting','froude','coldpool','foehn','oroprecip','valley','blocked'].includes(key)&&!data.orography)||(['stormwind','mpi','gpi','surge'].includes(key)&&!data.storms)||(['stp','helicity'].includes(key)&&!data.severe)||(['precip','accum'].includes(key)&&!data.precipitation)||(key==='clouds'&&!data.clouds)||(['cape','cloudbase','cloudtop'].includes(key)&&!data.coupled?.columns)||(key==='rainfall'&&!data.rain)||(key==='terrain'&&!data.terrain)||(['slope','aspect'].includes(key)&&!data.terrainDerivatives)||(key==='water'&&!data.surfaceWater)||(key==='soil'&&!data.surfaceWater?.soil_values)||(key==='cloud'&&!data.atmosphere)||(['pressure','humidity'].includes(key)&&!data.atmosphere&&!data.coupled)||(['density','moisture'].includes(key)&&!data.coupled)" @click="layer=key"><span>{{title}}<small>{{data.atmosphere&&key==='temperature'?'Synthetic regional field · °C':data.coupled&&key==='temperature'?'Coupled moist layer · °C':data.coupled&&key==='wind'?'Pressure · Coriolis · friction · m/s':data.coupled&&key==='pressure'?'Prescribed static field · hPa':data.coupled&&key==='humidity'?'Diagnosed from T, q, p · %':description}}</small></span><span>{{layer===key?'●':'○'}}</span></button><template v-if="data.atmosphere"><label class="toggle"><input type="checkbox" v-model="cloudsEnabled"> Cloud overlay</label><label class="toggle"><input type="checkbox" v-model="systemsEnabled"> Weather-system markers</label><p class="hint">Synthetic pressure, clouds and front. Cloud height is schematic; these fields do not drive the local physics.</p></template><p v-if="data.coupled" class="hint">Coupled engine run: wind from the static pressure field, Coriolis and friction; density diagnosed from temperature and humidity feeds back into the wind; temperature and humidity are carried by the wind with configurable diffusion.<br>Diffusion T {{data.coupled.request.diffusion.temperature_m2_s}} · q {{data.coupled.request.diffusion.humidity_m2_s}} · momentum {{data.coupled.request.diffusion.momentum_m2_s}} m²/s · friction {{data.coupled.request.atmosphere.surface_friction_coefficient_s}} 1/s · Coriolis {{data.coupled.request.atmosphere.coriolis_mode}} · density {{data.coupled.request.density_mode}}<template v-if="data.coupled.columns"><br>Vertical columns: hydrostatic layers, convective adjustment and a lifted surface parcel give cloud base, equilibrium level and CAPE per cell. Diagnostic only; no surface fluxes resupply heat or moisture.</template></p><template v-if="data.clouds"><label class="toggle"><input type="checkbox" v-model="cloudVolumes"> Cloud volumes (base → top)</label><label class="toggle"><input type="checkbox" v-model="frontOverlay"> Front overlay (blue cold · red warm · purple stationary)</label><p class="hint">{{data.clouds.synthetic?'Synthetic mock in the documented cloud-formation format; illustration only.':'Engine diagnosis: fronts from the temperature gradient, advection and convergence; convection from the heated surface parcel; combined where frontal lifting releases it.'}}<br>Heating now {{data.clouds.heating.toFixed(1)}} K · lifting over {{(data.clouds.config.lifting_time_scale_s/3600).toFixed(0)}} h · warm slope 1:{{(1/data.clouds.config.warm_front_slope).toFixed(0)}} · cold slope 1:{{(1/data.clouds.config.cold_front_slope).toFixed(0)}}</p></template><label class="toggle"><input type="checkbox" v-model="vectors"> Wind direction vectors</label><template v-if="data.terrain"><label class="toggle"><input type="checkbox" v-model="terrainEnabled"> Place fields on terrain</label><label class="toggle">Height scale {{exaggeration}}× <input aria-label="Terrain vertical exaggeration" type="range" min="1" max="5" step="0.5" v-model="exaggeration"></label><label v-if="data.terrainTemperature" class="toggle"><input type="checkbox" v-model="adjustedTemperature"> Terrain-adjusted temperature</label><p v-if="data.terrainTemperature" class="hint">Lapse rate {{data.terrainTemperature.lapse_rate_k_per_m*1000}} K/km · reference {{data.terrainTemperature.reference_elevation_m}} m<br>Diagnostic adjustment; no feedback into transport.</p><p class="hint">{{data.terrain.source_id}} · {{data.terrain.vertical_reference}}<br>Geometry is a display layer; lapse-rate adjustment is optional.</p></template></section>
   <section v-if="view==='map'" class="map-layers"><div class="section-label">01b / WEATHER MAP LAYERS</div><p class="hint">Switch layers on and off to compose the map. Engine or labelled mock output only; no rendering of external map tiles yet.</p>
    <label class="toggle">Base field <select v-model="mapLayers.base"><option value="temperature">Air temperature</option><option value="pressure">Surface pressure</option><option v-if="data.terrain" value="terrain">Terrain (hillshade)</option><option value="none">None (dark)</option></select></label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.relief" :disabled="!data.terrain"> Relief (3D terrain, height scale {{exaggeration}}×)</label>
    <label v-if="data.terrain" class="toggle">Height scale <input aria-label="Map relief exaggeration" type="range" min="1" max="5" step="0.5" v-model="exaggeration"></label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.lifting" :disabled="!data.orography"> Orographic lifting (blue up-slope · orange descent)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.foehn" :disabled="!data.orography"> Foehn cells (F)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.coldPools" :disabled="!data.orography"> Cold-air pools (❄)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.oroPrecip" :disabled="!data.orography"> Orographic precipitation (●)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.blocking" :disabled="!data.orography"> Blocked flow (Froude)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.isobars"> Isobars every <select v-model.number="mapLayers.isobarIntervalHpa"><option :value="1">1</option><option :value="2">2</option><option :value="4">4</option></select> hPa</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.fronts" :disabled="!data.clouds"> Fronts (cold blue · warm red · stationary purple)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.clouds" :disabled="!data.clouds"> Cloud cover by genus</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.volumes" :disabled="!data.clouds"> Cloud volumes (3D base → top)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.precipitation" :disabled="!data.precipitation"> Precipitation rate shading</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.symbols" :disabled="!data.precipitation"> Precipitation symbols (● rain ▽ showers ✱ snow ▲ sleet ’ drizzle)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.hazards" :disabled="!data.precipitation"> Thunderstorm ⚡ and hail ◆ markers</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.wind"> Wind vectors</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.landSea" :disabled="!data.surface"> Land / sea</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.storms" :disabled="!data.storms"> Tropical cyclones (centres, category, tracks, ✖ landfall ⊕ merger ✦ genesis)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.stormWind" :disabled="!data.storms"> Storm wind field (category colours)</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.surge" :disabled="!data.storms"> Storm surge on the coast</label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.tornado" :disabled="!data.severe"> Tornado risk (STP class) and 🌪 where possible</label>
    <p v-if="!data.clouds" class="hint">Load the cloud formation example or mock for fronts, clouds and precipitation layers.</p>
   </section>
   <section v-if="view==='water'" class="map-layers"><div class="section-label">01c / CATCHMENT LAYERS</div><p class="hint">Where the water goes: rivers sized by upstream area and coloured by discharge, lakes at their level, snow, overland water and rain over the relief. Click a cell to trace its water to the outlet.</p>
    <label class="toggle">Base <select v-model="waterLayers.base"><option value="terrain">Terrain (hillshade)</option><option value="basins">Drainage basins</option><option value="groundwater">Water-table depth (dark = deep)</option><option value="saturation">Soil saturation</option></select></label>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.relief"> Relief (3D terrain, height scale {{exaggeration}}×)</label>
    <label class="toggle">Height scale <input aria-label="Catchment relief exaggeration" type="range" min="1" max="5" step="0.5" v-model="exaggeration"></label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.rivers"> River network (width ∝ upstream area · brightness ∝ discharge)</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.lakes"> Lakes (depth above the lake floor)</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.labels"> Lake labels with level</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.surface"> Overland / floodplain water</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.snow"> Snowpack</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.rain"> Rainfall rate tint</label>
    <label class="toggle"><input type="checkbox" v-model="waterLayers.arrows"> Flow direction arrows (D8)</label>
   </section>
   <section v-if="view==='hazards'" class="map-layers"><div class="section-label">01d / HAZARD LAYERS</div><p class="hint">What massive rain does: flood depth × velocity classes, channels above bankfull in orange, erosion (red) and deposition (tan), landslides ▲ with debris runout, rainfall intensity–duration warnings (!) and slopes still unstable.</p>
    <label class="toggle"><input type="checkbox" v-model="mapLayers.relief"> Relief (3D terrain)</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.flood"> Flooding (<span v-for="c in FLOOD_CLASSES.slice(1)" :key="c.key" :style="{color:c.color}">■ {{c.key}} </span>)</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.sediment"> Erosion / deposition</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.landslides"> Landslides ▲ (up to the current time)</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.runout"> Debris runout paths</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.unstable"> Unstable slopes (failed, not yet drained)</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.threshold"> Rainfall intensity–duration threshold exceeded (!)</label>
    <label class="toggle"><input type="checkbox" v-model="hazardLayers.stability"> Factor of safety shading (red < 1 · orange < 1.3 · yellow < 2 · green)</label>
   </section>
   <section><div class="section-label">02 / DATA SOURCE</div><strong class="source">{{source}}</strong><p class="hint">{{source==='Synthetic demonstration'?'Illustrative fields only. These values are not engine output or live observations.':source==='Regional weather · synthetic'?'Analytic 1,200 × 900 km weather illustration. Low/high pressure, a moving front and cloud bands; not solver output.':source==='Engine output · synthetic inputs'?'C++ dry transport + radar rain estimation + accumulation + gridding. Synthetic inputs; not live weather.':source==='Engine output · coupled wind'?'C++ coupled wind / moist-layer model on synthetic Gaussian pressure systems. Pressure is prescribed; not live weather or a forecast.':source==='Engine output · cloud formation'?'C++ coupled model with column and cloud-formation diagnostics: cold/warm fronts, frontal and convective cloud, afternoon thunderstorms. Synthetic inputs; rule-of-thumb cloud types.':source==='Cloud formation · synthetic mock'?'Hand-built mock in the documented cloud-formation format (moving warm and cold fronts, diurnal convection, a synthetic hurricane and tornado risk). Not solver output.':source==='Engine output · Alps foehn'?'C++ coupled model over a synthetic east-west Alpine ridge with a foreland basin: southerly flow, orographic precipitation on the south side, foehn warming and drying to the north, nocturnal cold pools in the basin. Synthetic terrain; parametrised orography, not a forecast.':source==='Engine output · alpine flood'?'C++ catchment hydrology on a synthetic pre-alpine range draining to a southern sea: two days of stratiform rain, an eight-hour cloudburst on the range, then a shower. Rivers, lakes, groundwater, floods, erosion and landslides from the kernel; synthetic terrain and forcing, not a forecast.':source==='Engine output · hurricane landfall'?'C++ coupled model with tropical-cyclone objects: two seeds merge, the storm intensifies toward its potential intensity over a 29 °C sea, makes landfall on the western coast and decays inland. Synthetic inputs; parametrised storm physics, not a forecast.':'Loaded in this browser only. No upload service or database.'}}</p><button class="example-button" :disabled="loading" @click="loadEngineExample">{{loading?'Loading…':'→ Load engine example'}}</button><button class="example-button" :disabled="loading" @click="loadOutletExample">↘ Load outlet scenario</button><button class="example-button" :disabled="loading" @click="loadComparisonDemo">⇄ Compare hydrology scenarios</button><label v-if="data.surfaceWater" class="compare-upload">Open comparison JSON<input type="file" accept=".json,application/json" @change="uploadComparison"></label><button class="example-button" :disabled="loading" @click="loadCoupledExample">⇶ Load coupled wind example</button><button class="example-button" :disabled="loading" @click="loadCloudExample">⛅ Load cloud formation example</button><button class="example-button" :disabled="loading" @click="loadHurricaneExample">🌀 Load hurricane landfall example</button><button class="example-button" :disabled="loading" @click="loadAlpsExample">⛰ Load Alps foehn example</button><button class="example-button" :disabled="loading" @click="loadFloodExample">🌊 Load alpine flood example</button><button class="example-button" @click="useCloudMock">⛈ Cloud formation mock (synthetic)</button><button class="example-button" @click="useRegionalDemo">☁ Regional weather demo</button><button class="text-button" @click="useDemo">↻ Load synthetic demo</button></section>
   <section class="inspection"><div class="section-label">03 / CELL INSPECTOR</div><template v-if="chosen"><h2>{{values[chosen.i]===null?(layer==='aspect'?'Undefined (flat)':'No data'):values[chosen.i]?.toFixed(2)}} <small>{{unit}}</small></h2><p>Column {{chosen.x}} · Row {{chosen.y}} · Index {{chosen.i}}</p><p>East {{(grid.origin_east_m+(chosen.x+.5)*grid.spacing_east_m).toFixed(0)}} m · North {{(grid.origin_north_m+(chosen.y+.5)*grid.spacing_north_m).toFixed(0)}} m</p><p v-if="data.atmosphere">Cloud {{(data.atmosphere.cloud[chosen.i]*100).toFixed(1)}}% · Pressure {{data.atmosphere.pressure[chosen.i].toFixed(1)}} hPa<br>Relative humidity {{data.atmosphere.humidity[chosen.i].toFixed(1)}}%</p><p v-if="data.coupled">Pressure {{(data.coupled.pressure[chosen.i]/100).toFixed(1)}} hPa · Density {{data.coupled.density[chosen.i].toFixed(4)}} kg/m³<br>Specific humidity {{(data.coupled.specificHumidity[chosen.i]*1000).toFixed(2)}} g/kg · Relative humidity {{data.coupled.humidity[chosen.i].toFixed(1)}}%<br>Coriolis f {{data.coupled.coriolis[chosen.i].toExponential(3)}} 1/s</p><p v-if="data.clouds">Cloud: <strong>{{cloudTypeInfo(data.clouds.type[chosen.i]).label}}</strong><template v-if="data.clouds.type[chosen.i]!=='none'"> · base {{data.clouds.base[chosen.i].toFixed(0)}} m · top {{data.clouds.top[chosen.i].toFixed(0)}} m · cover {{(data.clouds.fraction[chosen.i]*100).toFixed(0)}}%<br>Mechanism {{data.clouds.mechanism[chosen.i]}} · trigger {{data.clouds.trigger[chosen.i]}}{{data.clouds.thunderstorm[chosen.i]?' · thunderstorm':''}}</template><br>Front {{data.clouds.frontType[chosen.i]}} · |∇T| {{(data.clouds.gradient[chosen.i]*1e5).toFixed(2)}} K/100 km · advection {{(data.clouds.advection[chosen.i]*3600).toFixed(2)}} K/h · divergence {{data.clouds.divergence[chosen.i].toExponential(2)}} 1/s<br>{{data.clouds.distance[chosen.i]===null?'No front in the domain':`Nearest front ${(data.clouds.distance[chosen.i]/1000).toFixed(0)} km · ${data.clouds.side[chosen.i]===1?'warm side':data.clouds.side[chosen.i]===-1?'cold side':'on the front'}`}} · lifting {{data.clouds.lifting[chosen.i].toFixed(0)}} m · heated CAPE {{data.clouds.cape[chosen.i].toFixed(0)}} / CIN {{data.clouds.cin[chosen.i].toFixed(0)}} J/kg</p><p v-if="data.precipitation">Precipitation: <strong>{{precipitationTypeInfo(data.precipitation.type[chosen.i]).label}}</strong><template v-if="data.precipitation.type[chosen.i]!=='none'"> · {{data.precipitation.intensity[chosen.i]}} {{data.precipitation.character[chosen.i]}} · {{data.precipitation.rate[chosen.i].toFixed(2)}} mm/h for {{(data.precipitation.duration[chosen.i]*100).toFixed(0)}}% of the interval → {{data.precipitation.accumulation[chosen.i].toFixed(1)}} mm · phase {{data.precipitation.phase[chosen.i]}}</template><template v-if="data.precipitation.virga[chosen.i]"> · virga (evaporates aloft)</template><br>{{data.precipitation.hazards[chosen.i].length?data.precipitation.hazards[chosen.i].map(h=>HAZARD_LABELS[h]).join(' · '):'no hazards'}}<template v-if="data.precipitation.hail[chosen.i]>0"> · hail up to {{data.precipitation.hail[chosen.i].toFixed(1)}} cm</template><br>Wet-bulb {{(data.precipitation.wetBulb[chosen.i]-273.15).toFixed(1)}} °C · freezing level {{data.precipitation.freezingLevel[chosen.i]===null?'none':data.precipitation.freezingLevel[chosen.i].toFixed(0)+' m'}} · precipitable water {{data.precipitation.precipitableWater[chosen.i].toFixed(1)}} mm<template v-if="data.precipitation.baseTemperature[chosen.i]!==null"> · cloud {{(data.precipitation.baseTemperature[chosen.i]-273.15).toFixed(0)}} °C at base, {{(data.precipitation.topTemperature[chosen.i]-273.15).toFixed(0)}} °C at top · lifting {{data.precipitation.updraft[chosen.i].toFixed(2)}} m/s</template></p><p v-if="data.orography">Orography: elevation {{data.terrain.values[chosen.i].toFixed(0)}} m · surface pressure {{(data.orography.surfacePressure[chosen.i]/100).toFixed(1)}} hPa · lifting {{data.orography.lifting[chosen.i].toFixed(3)}} m/s ({{data.orography.lifting[chosen.i]>0.01?'up-slope':data.orography.lifting[chosen.i]<-0.01?'descending':'level'}}) · contour {{data.orography.orientation[chosen.i]===null?'flat':data.orography.orientation[chosen.i].toFixed(0)+'° from north'}}<br>Cross-barrier {{data.orography.cross[chosen.i].toFixed(1)}} m/s · along-barrier {{data.orography.along[chosen.i].toFixed(1)}} m/s · obstacle ahead {{data.orography.obstacle[chosen.i].toFixed(0)}} m · Froude {{data.orography.froude[chosen.i]===null?'—':data.orography.froude[chosen.i].toFixed(2)}} · blocked {{(data.orography.blocked[chosen.i]*100).toFixed(0)}}%<br>Valley depth {{data.orography.valley[chosen.i].toFixed(0)}} m · cold pool {{data.orography.coldPool[chosen.i].toFixed(1)}} K{{data.orography.coldPoolFlag[chosen.i]?' ❄':''}} · foehn {{data.orography.foehn[chosen.i]?`+${data.orography.foehnWarming[chosen.i].toFixed(1)} K`:'no'}} · orographic precipitation {{data.orography.precipRate[chosen.i].toFixed(2)}} mm/h ({{data.orography.cumulative[chosen.i].toFixed(1)}} mm so far)</p><p v-if="data.hydrology">Catchment: <strong>{{data.hydrology.network.ocean[chosen.i]?'sea':data.hydrology.network.lake_id[chosen.i]>=0?`lake ${data.hydrology.network.lake_id[chosen.i]+1}`:data.hydrology.network.channel[chosen.i]?`river reach (Strahler ${data.hydrology.network.strahler_order[chosen.i]})`:'hillslope'}}</strong><template v-if="!data.hydrology.network.ocean[chosen.i]"> · upstream {{data.hydrology.network.upstream_area_km2[chosen.i].toFixed(0)}} km² · {{pathSummary}}<br>Rain {{data.hydrology.rain[chosen.i].toFixed(1)}} mm/h · snow {{data.hydrology.snow[chosen.i].toFixed(0)}} mm · surface water {{data.hydrology.surface[chosen.i].toFixed(1)}} mm · soil {{(data.hydrology.saturation[chosen.i]*100).toFixed(0)}} % saturated · water table {{data.hydrology.waterTable[chosen.i].toFixed(1)}} m down<template v-if="data.hydrology.network.channel[chosen.i]"><br>Discharge {{data.hydrology.discharge[chosen.i].toFixed(2)}} m³/s · depth {{data.hydrology.channelDepth[chosen.i].toFixed(2)}} / bankfull {{data.hydrology.network.bankfull_depth_m[chosen.i].toFixed(2)}} m · width {{data.hydrology.network.channel_width_m[chosen.i].toFixed(0)}} m · sediment {{data.hydrology.sediment[chosen.i].toFixed(2)}} kg/s</template><template v-if="data.hydrology.network.lake_id[chosen.i]>=0"><br>Lake level {{data.hydrology.lakeLevel[data.hydrology.network.lake_id[chosen.i]].toFixed(1)}} m · depth here {{data.hydrology.lakeDepth[chosen.i].toFixed(1)}} m · volume {{(data.hydrology.lakeVolume[data.hydrology.network.lake_id[chosen.i]]/1e6).toFixed(2)}} / {{(data.hydrology.network.lakes[data.hydrology.network.lake_id[chosen.i]].capacity_m3/1e6).toFixed(2)}} hm³</template><br>Hazards: flood <strong :style="{color:floodClassInfo(data.hydrology.floodClass[chosen.i]).color||'inherit'}">{{floodClassInfo(data.hydrology.floodClass[chosen.i]).key}}</strong> · erosion {{data.hydrology.erosion[chosen.i].toFixed(2)}} mm · deposition {{data.hydrology.deposition[chosen.i].toFixed(2)}} mm · factor of safety {{data.hydrology.fs[chosen.i]===null?'n/a (flat or water)':data.hydrology.fs[chosen.i].toFixed(2)}}{{data.hydrology.landslide[chosen.i]?' · ▲ landslide this step':data.hydrology.unstable[chosen.i]?' · unstable':''}}{{data.hydrology.threshold[chosen.i]?' · ! rainfall threshold exceeded':''}} · regolith {{data.hydrology.network.regolith_depth_m[chosen.i].toFixed(2)}} m · slope {{(Math.atan(data.hydrology.network.slope[chosen.i])*180/Math.PI).toFixed(1)}}°</template></p><p v-if="data.storms">Storm environment: {{data.surface?.land[chosen.i]?'land':'ocean'}}{{data.surface&&!data.surface.land[chosen.i]?` · SST ${(data.surface.sst[chosen.i]-273.15).toFixed(1)} °C`:''}} · potential intensity {{data.storms.env.potential_intensity_m_s[chosen.i].toFixed(0)}} m/s · genesis index {{data.storms.env.genesis_potential_index[chosen.i].toFixed(1)}} · shear {{data.storms.env.vertical_shear_m_s[chosen.i].toFixed(1)}} m/s · vorticity {{data.storms.env.relative_vorticity_s[chosen.i].toExponential(2)}} 1/s<br>Storm wind here {{data.storms.env.storm_wind_speed_m_s[chosen.i].toFixed(1)}} m/s · pressure anomaly {{(data.storms.env.storm_pressure_anomaly_pa[chosen.i]/100).toFixed(1)}} hPa · storm rain {{data.storms.env.storm_rain_rate_mm_h[chosen.i].toFixed(1)}} mm/h<template v-if="data.storms.env.storm_surge_m[chosen.i]>0"> · surge {{data.storms.env.storm_surge_m[chosen.i].toFixed(2)}} m</template></p><p v-if="data.severe">Severe: STP {{data.severe.stp[chosen.i].toFixed(2)}} ({{data.severe.risk[chosen.i]}}){{data.severe.possible[chosen.i]?' · 🌪 tornado possible':''}} · 0–1 km shear {{data.severe.shear1[chosen.i].toFixed(1)}} m/s · deep shear {{data.severe.shear6[chosen.i].toFixed(1)}} m/s · helicity {{data.severe.helicity[chosen.i].toFixed(0)}} m²/s²<br>Heated CAPE {{data.severe.cape[chosen.i].toFixed(0)}} / CIN {{data.severe.cin[chosen.i].toFixed(0)}} J/kg · cap {{data.severe.cap[chosen.i].toFixed(0)}} J/kg {{data.severe.capped[chosen.i]?(data.severe.capBroken[chosen.i]?'(broken)':'(holding)'):'(none)'}} · storm motion ({{data.severe.motionEast[chosen.i].toFixed(1)}}, {{data.severe.motionNorth[chosen.i].toFixed(1)}}) m/s</p><p v-if="data.coupled?.columns">Column ({{data.coupled.columns.config.layer_count}} × {{data.coupled.columns.config.layer_thickness_m}} m): LCL {{data.coupled.columns.lcl[chosen.i]===null?'none':data.coupled.columns.lcl[chosen.i].toFixed(0)+' m'}} · LFC {{data.coupled.columns.lfc[chosen.i]===null?'none':data.coupled.columns.lfc[chosen.i].toFixed(0)+' m'}} · EL {{data.coupled.columns.el[chosen.i]===null?'none':data.coupled.columns.el[chosen.i].toFixed(0)+' m'}}<br>CAPE {{data.coupled.columns.cape[chosen.i].toFixed(0)}} J/kg · CIN {{data.coupled.columns.cin[chosen.i].toFixed(0)}} J/kg · potential {{data.coupled.columns.potential[chosen.i]}} · condensed {{data.coupled.columns.condensed[chosen.i].toFixed(3)}} kg/m²</p><p v-if="data.terrainTemperature && layer==='temperature'">Reference temperature {{(forecast.fields.air_temperature.values[chosen.i]-273.15).toFixed(2)}} °C<br>Terrain correction {{(data.terrainTemperature.values[chosen.i]-forecast.fields.air_temperature.values[chosen.i]).toFixed(2)}} K</p><p v-if="data.terrainDerivatives">Slope {{data.terrainDerivatives.slope_deg[chosen.i].toFixed(2)}}° · Aspect {{data.terrainDerivatives.aspect_deg[chosen.i]===null?'flat / undefined':data.terrainDerivatives.aspect_deg[chosen.i].toFixed(1)+'°'}}</p><p v-if="data.terrain">Elevation {{data.terrain.values[chosen.i].toFixed(2)}} m · {{data.terrain.vertical_reference}}</p><p v-if="layer==='rainfall'">Quality: {{data.rain.quality[chosen.i]}}</p></template><p v-else class="hint">Select a cell in the scene to inspect its value and local coordinates.</p></section>
   <section class="request"><div class="section-label">04 / COUPLED WIND REQUEST</div><p class="hint">Edit the time steps, grid, atmosphere, diffusion and pressure systems, download the request and run <code>terraflux-run-coupled-wind</code>. No physics runs in the browser; checks mirror the solver bounds.</p>
    <div class="request-form">
     <label class="wide">Start time (UTC)<input v-model="coupledForm.start_time_utc"></label>
     <label>Timestep s<input type="number" min="1" v-model.number="coupledForm.timestep_seconds"></label><label>Steps<input type="number" min="1" step="1" v-model.number="coupledForm.steps"></label>
     <label>Snapshot every N steps<input type="number" min="1" step="1" v-model.number="coupledForm.snapshot_every_steps"></label><label>Density mode<select v-model="coupledForm.density_mode"><option v-for="m in DENSITY_MODES" :key="m" :value="m">{{m}}</option></select></label>
     <label>Cells east (nx)<input type="number" min="2" step="1" v-model.number="coupledForm.nx"></label><label>Cells north (ny)<input type="number" min="2" step="1" v-model.number="coupledForm.ny"></label>
     <label>Spacing east m<input type="number" min="1" v-model.number="coupledForm.spacing_east_m"></label><label>Spacing north m<input type="number" min="1" v-model.number="coupledForm.spacing_north_m"></label>
     <label>Anchor latitude °<input type="number" step="0.1" v-model.number="coupledForm.geographic_anchor_latitude_deg"></label><label>Anchor longitude °<input type="number" step="0.1" v-model.number="coupledForm.geographic_anchor_longitude_deg"></label>
     <label>Coriolis mode<select v-model="coupledForm.coriolis_mode"><option v-for="m in CORIOLIS_MODES" :key="m" :value="m">{{m}}</option></select></label><label>Prescribed f 1/s<input type="number" step="1e-5" :disabled="coupledForm.coriolis_mode!=='prescribed'" v-model.number="coupledForm.coriolis_parameter_s"></label>
     <label>Air density kg/m³<input type="number" step="0.001" v-model.number="coupledForm.air_density_kg_m3"></label><label>Friction k 1/s<input type="number" step="1e-6" v-model.number="coupledForm.surface_friction_coefficient_s"></label>
     <label>Temperature diffusion m²/s<input type="number" min="0" v-model.number="coupledForm.temperature_diffusivity_m2_s"></label><label>Humidity diffusion m²/s<input type="number" min="0" v-model.number="coupledForm.humidity_diffusivity_m2_s"></label>
     <label>Momentum diffusion m²/s<input type="number" min="0" v-model.number="coupledForm.momentum_diffusivity_m2_s"></label><label>Scalar boundary<select v-model="coupledForm.scalar_boundary"><option v-for="m in SCALAR_BOUNDARIES" :key="m" :value="m">{{m}}</option></select></label>
     <label>Gradient boundary<select v-model="coupledForm.pressure_gradient_boundary"><option v-for="m in GRADIENT_BOUNDARIES" :key="m" :value="m">{{m}}</option></select></label><label>Background pressure Pa<input type="number" v-model.number="coupledForm.background_pressure_pa"></label>
     <label>Background temperature K<input type="number" step="0.1" v-model.number="coupledForm.background_temperature_k"></label><label>Background humidity kg/kg<input type="number" step="0.001" v-model.number="coupledForm.background_humidity_kg_kg"></label>
    </div>
    <label class="toggle"><input type="checkbox" v-model="coupledForm.column_enabled"> Vertical column diagnostics (layers, cloud base, CAPE)</label>
    <div v-if="coupledForm.column_enabled" class="request-form">
     <label>Layers<input type="number" min="2" step="1" v-model.number="coupledForm.column_layer_count"></label><label>Layer thickness m<input type="number" min="1" v-model.number="coupledForm.column_layer_thickness_m"></label>
     <label>Environment lapse rate K/m<input type="number" step="0.0005" v-model.number="coupledForm.column_lapse_rate_k_m"></label><label>Tropopause height m<input type="number" min="0" v-model.number="coupledForm.column_tropopause_height_m"></label>
     <label>Humidity scale height m<input type="number" min="1" v-model.number="coupledForm.column_humidity_scale_height_m"></label><label>Parcel step m<input type="number" min="1" v-model.number="coupledForm.column_parcel_step_m"></label>
    </div>
    <label v-if="coupledForm.column_enabled" class="toggle"><input type="checkbox" v-model="coupledForm.inversion_enabled"> Temperature inversion (capping layer storing convective energy)</label>
    <div v-if="coupledForm.column_enabled&&coupledForm.inversion_enabled" class="request-form">
     <label>Inversion base m<input type="number" min="0" v-model.number="coupledForm.inversion_base_m"></label><label>Inversion depth m<input type="number" min="1" v-model.number="coupledForm.inversion_depth_m"></label>
     <label>Inversion strength K<input type="number" min="0" step="0.5" v-model.number="coupledForm.inversion_strength_k"></label><label>Lapse rate above K/m<input type="number" step="0.0005" v-model.number="coupledForm.lapse_rate_above_inversion_k_m"></label>
    </div>
    <div v-for="(c,i) in coupledForm.centers" :key="i" class="center-row"><div class="center-head"><strong>{{c.kind==='low'?'L':'H'}} · Pressure system {{i+1}}</strong><button class="text-button" @click="removeCenter(i)">remove</button></div><div class="request-form">
     <label>Kind<select v-model="c.kind"><option value="high">high</option><option value="low">low</option></select></label><label>Radius m<input type="number" min="1" v-model.number="c.radius_m"></label>
     <label>East m<input type="number" v-model.number="c.east_m"></label><label>North m<input type="number" v-model.number="c.north_m"></label>
     <label>Δ pressure Pa<input type="number" v-model.number="c.pressure_anomaly_pa"></label><label>Δ temperature K<input type="number" step="0.1" v-model.number="c.temperature_anomaly_k"></label>
     <label class="wide">Δ specific humidity kg/kg<input type="number" step="0.001" v-model.number="c.humidity_anomaly_kg_kg"></label>
    </div></div>
    <button class="text-button" @click="addCenter">+ add pressure system</button>
    <div v-for="(a,i) in coupledForm.airmasses" :key="'a'+i" class="center-row"><div class="center-head"><strong>Air mass {{i+1}} (temperature / humidity anomaly)</strong><button class="text-button" @click="removeAirmass(i)">remove</button></div><div class="request-form">
     <label>East m<input type="number" v-model.number="a.east_m"></label><label>North m<input type="number" v-model.number="a.north_m"></label>
     <label>Radius m<input type="number" min="1" v-model.number="a.radius_m"></label><label>Δ temperature K<input type="number" step="0.1" v-model.number="a.temperature_anomaly_k"></label>
     <label class="wide">Δ specific humidity kg/kg<input type="number" step="0.001" v-model.number="a.humidity_anomaly_kg_kg"></label>
    </div></div>
    <button class="text-button" @click="addAirmass">+ add air mass (warm sector / cold pool)</button>
    <label class="toggle"><input type="checkbox" v-model="coupledForm.cloud_enabled" :disabled="!coupledForm.column_enabled"> Cloud formation (fronts, convection, thunderstorms; needs the column)</label>
    <div v-if="coupledForm.cloud_enabled" class="request-form">
     <label>Diurnal heating amplitude K<input type="number" min="0" step="0.5" v-model.number="coupledForm.cloud_heating_amplitude_k"></label><label>Heating phase s (sunrise offset)<input type="number" step="600" v-model.number="coupledForm.cloud_heating_phase_seconds"></label>
     <label v-for="[key,label] in CLOUD_CONFIG_KEYS" :key="key">{{label}}<input type="number" step="any" v-model.number="coupledForm.cloud[key]"></label>
    </div>
    <label v-if="coupledForm.cloud_enabled" class="toggle"><input type="checkbox" v-model="coupledForm.severe_enabled"> Severe convection (tornado parameter from the inversion, low-level shear and helicity)</label>
    <label v-if="coupledForm.cloud_enabled" class="toggle"><input type="checkbox" v-model="coupledForm.precip_enabled"> Precipitation outcomes (rain, snow, sleet, hail, thunderstorms)</label>
    <div v-if="coupledForm.cloud_enabled&&coupledForm.precip_enabled" class="request-form">
     <label v-for="[key,label] in PRECIP_CONFIG_KEYS" :key="key">{{label}}<input type="number" step="any" v-model.number="coupledForm.precip[key]"></label>
    </div>
    <label class="toggle"><input type="checkbox" v-model="coupledForm.orography_enabled"> Orography: mountain ridges (orientation!), basins, foehn, blocking, valley cold pools</label>
    <template v-if="coupledForm.orography_enabled">
     <div class="request-form"><label>Base elevation m<input type="number" v-model.number="coupledForm.terrain_base_elevation_m"></label><label v-for="[key,label] in OROGRAPHY_KEYS" :key="key">{{label}}<input type="number" step="any" v-model.number="coupledForm.orography[key]"></label></div>
     <div v-for="(r,i) in coupledForm.ridges" :key="'ridge'+i" class="center-row"><div class="center-head"><strong>Ridge {{i+1}} · {{r.orientation_deg%180===0?'north–south (blocks zonal flow)':Math.abs(r.orientation_deg%180)===90?'east–west (blocks north–south exchange)':r.orientation_deg+'°'}}</strong><button class="text-button" @click="removeRidge(i)">remove</button></div><div class="request-form">
      <label>Axis orientation ° (0 = N–S, 90 = E–W)<input type="number" step="15" v-model.number="r.orientation_deg"></label><label>Height m<input type="number" min="0" v-model.number="r.height_m"></label>
      <label>Centre east m<input type="number" v-model.number="r.center_east_m"></label><label>Centre north m<input type="number" v-model.number="r.center_north_m"></label>
      <label>Half width m<input type="number" min="1" v-model.number="r.half_width_m"></label><label>Length m<input type="number" min="1" v-model.number="r.length_m"></label>
     </div></div>
     <button class="text-button" @click="addRidge">+ add ridge</button>
     <div v-for="(b,i) in coupledForm.basins" :key="'basin'+i" class="center-row"><div class="center-head"><strong>Basin / valley {{i+1}}</strong><button class="text-button" @click="removeBasin(i)">remove</button></div><div class="request-form">
      <label>Centre east m<input type="number" v-model.number="b.center_east_m"></label><label>Centre north m<input type="number" v-model.number="b.center_north_m"></label>
      <label>Depth m<input type="number" min="0" v-model.number="b.depth_m"></label><label>Radius m<input type="number" min="1" v-model.number="b.radius_m"></label>
     </div></div>
     <button class="text-button" @click="addBasin">+ add basin</button>
    </template>
    <label class="toggle"><input type="checkbox" v-model="coupledForm.surface_enabled"> Surface: straight coastline and sea-surface temperature</label>
    <div v-if="coupledForm.surface_enabled" class="request-form">
     <label>Coast position east m<input type="number" v-model.number="coupledForm.coast_east_m"></label><label>Land side<select v-model="coupledForm.land_side"><option value="west">west</option><option value="east">east</option></select></label>
     <label>Sea-surface temperature K<input type="number" step="0.1" v-model.number="coupledForm.sea_surface_temperature_k"></label><label>SST gradient north K/m<input type="number" step="1e-6" v-model.number="coupledForm.sst_gradient_north_k_per_m"></label>
    </div>
    <label v-if="coupledForm.surface_enabled&&coupledForm.column_enabled" class="toggle"><input type="checkbox" v-model="coupledForm.storms_enabled"> Tropical cyclones (genesis, intensity, Fujiwhara, merger, landfall) with default storm physics</label>
    <template v-if="coupledForm.surface_enabled&&coupledForm.column_enabled&&coupledForm.storms_enabled">
     <div v-for="(x,i) in coupledForm.storm_seeds" :key="'seed'+i" class="center-row"><div class="center-head"><strong>Storm seed {{i+1}}</strong><button class="text-button" @click="removeSeed(i)">remove</button></div><div class="request-form">
      <label>East m<input type="number" v-model.number="x.east_m"></label><label>North m<input type="number" v-model.number="x.north_m"></label>
      <label>Max wind m/s<input type="number" min="1" v-model.number="x.max_wind_m_s"></label><label>Radius of max wind m<input type="number" min="1" v-model.number="x.radius_max_wind_m"></label>
     </div></div>
     <button class="text-button" @click="addSeed">+ add storm seed</button>
    </template>
    <ul class="report"><li v-for="e in coupledReport.errors" :key="e" class="report-error">✕ {{e}}</li><li v-for="w in coupledReport.warnings" :key="w" class="report-warn">△ {{w}}</li><li v-if="!coupledReport.errors.length" class="report-ok">✓ Request passes the configuration checks</li></ul>
    <p v-if="!coupledReport.errors.length" class="hint">f {{coupledReport.estimates.coriolis_parameter_s?.toExponential(3)}} 1/s · inertial period {{fmt(coupledReport.estimates.inertial_period_h,1)}} h · friction time {{fmt(coupledReport.estimates.friction_time_h,1)}} h · cross-isobar angle {{fmt(coupledReport.estimates.cross_isobar_angle_deg,1)}}°<br>Δt(|f|+k) {{fmt(coupledReport.estimates.coriolis_friction_number,3)}} · momentum diffusion number {{fmt(coupledReport.estimates.momentum_diffusion_number,3)}} · scalar stability estimate at spin-up peak {{fmt(coupledReport.estimates.scalar_stability_estimate,2)}}<br>Balanced wind ≈ {{fmt(coupledReport.estimates.balanced_speed_estimate_m_s,1)}} m/s · peak ≈ {{fmt(coupledReport.estimates.peak_speed_estimate_m_s,1)}} m/s · upwind numerical diffusion ≈ {{fmt(coupledReport.estimates.numerical_diffusivity_estimate_m2_s,0)}} m²/s<template v-if="coupledReport.estimates.column_top_m"><br>Column top {{fmt(coupledReport.estimates.column_top_m/1000,1)}} km</template></p>
    <div class="comparison-switch"><button :disabled="coupledReport.errors.length>0" @click="downloadCoupledRequest">⇩ Download request JSON</button><button v-if="data.coupled" @click="useLoadedCoupledSettings">Use loaded run's settings</button><button @click="resetCoupledForm">Reset to example</button></div>
    <p v-if="coupledNote" class="hint">{{coupledNote}}</p>
   </section>
  </aside><article><div class="scene-head"><div><span class="eyebrow">FIELD EXPLORER</span><h2>{{layer==='temperature'?(adjustedTemperature?'Terrain-adjusted temperature':'Air temperature'):layer==='wind'?'Wind speed':layer==='terrain'?'Terrain elevation':layer==='slope'?'Terrain slope':layer==='aspect'?'Downhill aspect':layer==='water'?'Surface water depth':layer==='soil'?'Soil water storage':layer==='cloud'?'Cloud cover':layer==='pressure'?'Sea-level pressure':layer==='humidity'?'Relative humidity':layer==='density'?'Air density':layer==='moisture'?'Specific humidity':layer==='cape'?'Convective available potential energy':layer==='cloudbase'?'Cloud base (lifting condensation level)':layer==='cloudtop'?'Equilibrium level':layer==='clouds'?'Cloud formation · fronts and convection':layer==='precip'?'Precipitation rate at the ground':layer==='accum'?'Precipitation accumulated over the snapshot interval':layer==='stormwind'?'Tropical cyclone wind field':layer==='mpi'?'Maximum potential intensity':layer==='gpi'?'Genesis potential index':layer==='surge'?'Storm surge estimate':layer==='stp'?'Significant tornado parameter':layer==='helicity'?'Storm-relative helicity':layer==='lifting'?'Orographic lifting (up-slope positive)':layer==='blocked'?'Froude blocking of the cross-barrier flow':layer==='foehn'?'Foehn warming on the lee':layer==='coldpool'?'Cold-air pool deficit':layer==='oroprecip'?'Orographic precipitation rate':layer==='valley'?'Valley depth':layer==='discharge'?'River discharge':layer==='surfacewater'?'Surface and floodplain water':layer==='saturation'?'Soil saturation':layer==='watertable'?'Water-table depth below ground':layer==='snowpack'?'Snowpack water equivalent':layer==='erosion'?'Cumulative erosion':layer==='deposition'?'Cumulative deposition':layer==='stability'?'Slope factor of safety':layer==='floodclass'?'Flood hazard class':'Rainfall accumulation'}}</h2></div><div class="view-switch"><button :class="{selected:view==='field'}" @click="view='field'">Field explorer</button><button :class="{selected:view==='map'}" :disabled="!data.coupled" @click="view='map'">Weather map</button><button :class="{selected:view==='water'}" :disabled="!data.hydrology" @click="view='water'">Catchment</button><button :class="{selected:view==='hazards'}" :disabled="!data.hydrology" @click="view='hazards'">Hazards</button><button class="reset" @click="reset">↺ Reset view</button></div></div><div class="viewport" ref="host" aria-label="Interactive 3D weather grid"><div v-if="fallback" class="fallback-grid" :style="{gridTemplateColumns:`repeat(${grid.nx},1fr)`}"><button v-for="(value,i) in values" :key="i" :aria-label="`Cell ${i}: ${value===null?'no data':value.toFixed(2)} ${unit}`" :style="{gridRow:grid.ny-Math.floor(i/grid.nx),gridColumn:i%grid.nx+1,background:view!=='field'?mapCellStyles[i]:value===null?'#283b49':layer==='clouds'?CLOUD_TYPES[value].color:`hsl(${hue(value)} ${layer==='cloud'?15:70}% ${layer==='cloud'?18+value*.72:50}%)`}" @click="selected=i"></button></div><svg v-if="fallback && data.atmosphere" class="systems-map" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Synthetic cloud and weather-system overlay"><template v-if="cloudsEnabled"><ellipse v-for="(c,i) in data.atmosphere.cloud" :key="'cloud'+i" v-show="i%3===0 && c>.35" :cx="((i%grid.nx)+.5)/grid.nx*100" :cy="(1-(Math.floor(i/grid.nx)+.5)/grid.ny)*100" :rx="2.1" :ry="1.7" fill="#e9f5ff" :opacity="c*.32"/></template><template v-if="systemsEnabled"><template v-for="(s,i) in data.atmosphere.systems" :key="i"><polyline v-if="s.kind==='cold_front'" :points="s.points.map(([u,v])=>`${u*100},${(1-v)*100}`).join(' ')" fill="none" stroke="#85ccff" stroke-width=".7" stroke-dasharray="2 1"/><text v-else :x="s.u*100" :y="(1-s.v)*100" :fill="s.kind==='low'?'#ffb39c':'#c5e9ff'" font-size="7" font-weight="bold" text-anchor="middle">{{s.kind==='low'?'L':'H'}}</text></template></template></svg><svg v-if="fallback && view==='map'" class="systems-map" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Weather map overlays"><template v-for="level in isobarLines" :key="level.level_pa"><polyline v-for="(line,li) in level.lines" :key="li" :points="line.map(([u,v])=>`${u*100},${(1-v)*100}`).join(' ')" fill="none" :stroke="Math.round(level.level_hpa)%(mapLayers.isobarIntervalHpa*2)===0?'#f3f7f9':'#a9bcc6'" :stroke-width="Math.round(level.level_hpa)%(mapLayers.isobarIntervalHpa*2)===0?.5:.3"/><text v-if="Math.round(level.level_hpa)%(mapLayers.isobarIntervalHpa*2)===0&&level.lines[0]" :x="level.lines[0][0][0]*100" :y="(1-level.lines[0][0][1])*100" font-size="2.6" fill="#f3f7f9">{{Math.round(level.level_hpa)}}</text></template><template v-if="mapLayers.fronts&&data.clouds"><template v-for="(t,i) in data.clouds.frontType" :key="'f'+i"><rect v-if="t!=='none'" :x="(i%grid.nx)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+1)/grid.ny)*100" :width="100/grid.nx" :height="100/grid.ny" :fill="FRONT_COLORS[t]" opacity=".5"/></template></template><template v-if="mapLayers.symbols&&data.precipitation"><template v-for="(t,i) in data.precipitation.type" :key="'p'+i"><text v-if="t!=='none'&&(i%grid.nx)%symbolStride===0&&Math.floor(i/grid.nx)%symbolStride===0" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.3)/grid.ny)*100" font-size="2.8" text-anchor="middle" :fill="data.precipitation.phase[i]==='solid'?'#ffffff':'#bfe0ff'">{{precipitationTypeInfo(t).symbol}}</text></template></template><template v-if="mapLayers.storms&&data.storms"><template v-for="s in data.storms.list" :key="'st'+s.id"><polyline v-if="s.track.length>1" :points="s.track.map(([e,n])=>`${(e-grid.origin_east_m)/(grid.nx*grid.spacing_east_m)*100},${(1-(n-grid.origin_north_m)/(grid.ny*grid.spacing_north_m))*100}`).join(' ')" fill="none" stroke="#ffffff" stroke-width=".4" opacity=".7"/><circle :cx="(s.east_m-grid.origin_east_m)/(grid.nx*grid.spacing_east_m)*100" :cy="(1-(s.north_m-grid.origin_north_m)/(grid.ny*grid.spacing_north_m))*100" :r="Math.max(1.5,s.radius_max_wind_m/(grid.nx*grid.spacing_east_m)*100)" fill="none" :stroke="categoryInfo(s.category).color" stroke-width=".8"/><text :x="(s.east_m-grid.origin_east_m)/(grid.nx*grid.spacing_east_m)*100" :y="(1-(s.north_m-grid.origin_north_m)/(grid.ny*grid.spacing_north_m))*100-2.5" font-size="3" text-anchor="middle" :fill="categoryInfo(s.category).color">{{categoryInfo(s.category).short}}</text></template><text v-for="(e,i) in visibleEvents.filter(e=>['landfall','merger','genesis'].includes(e.kind))" :key="'ev'+i" :x="(e.east_m-grid.origin_east_m)/(grid.nx*grid.spacing_east_m)*100" :y="(1-(e.north_m-grid.origin_north_m)/(grid.ny*grid.spacing_north_m))*100+1" font-size="3" text-anchor="middle" :fill="e.kind==='landfall'?'#ff5c5c':'#ffffff'">{{e.kind==='landfall'?'✖':e.kind==='merger'?'⊕':'✦'}}</text></template><template v-if="data.orography"><template v-for="(b,i) in data.orography.foehn" :key="'fo'+i"><text v-if="mapLayers.foehn&&b" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.4)/grid.ny)*100" font-size="3" text-anchor="middle" fill="#ff8c42">F</text></template><template v-for="(b,i) in data.orography.coldPoolFlag" :key="'cp'+i"><text v-if="mapLayers.coldPools&&b" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.4)/grid.ny)*100" font-size="3" text-anchor="middle" fill="#dff3ff">❄</text></template></template><template v-if="mapLayers.tornado&&data.severe"><template v-for="(b,i) in data.severe.possible" :key="'t'+i"><text v-if="b" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.5)/grid.ny)*100" font-size="3.2" text-anchor="middle">🌪</text></template></template><template v-if="mapLayers.hazards&&data.precipitation"><template v-for="(b,i) in data.precipitation.lightning" :key="'h'+i"><text v-if="b" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.7)/grid.ny)*100" font-size="3" text-anchor="middle" fill="#ffd166">{{data.precipitation.hail[i]>0?'⚡◆':'⚡'}}</text></template></template></svg><svg v-if="fallback && view==='field' && data.clouds && frontOverlay" class="systems-map" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Front overlay"><template v-for="(t,i) in data.clouds.frontType" :key="i"><rect v-if="t!=='none'" :x="(i%grid.nx)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+1)/grid.ny)*100" :width="100/grid.nx" :height="100/grid.ny" :fill="FRONT_COLORS[t]" opacity=".55"/></template><template v-for="(s,i) in data.clouds.thunderstorm" :key="'s'+i"><text v-if="s" :x="((i%grid.nx)+.5)/grid.nx*100" :y="(1-(Math.floor(i/grid.nx)+.3)/grid.ny)*100" font-size="3" text-anchor="middle" fill="#ffd166">⚡</text></template></svg><svg v-if="fallback && data.surfaceWater?.outlets?.length" class="systems-map" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Configured surface outlet locations"><circle v-for="(o,i) in data.surfaceWater.outlets" :key="i" :cx="(o.x+.5)/grid.nx*100" :cy="(1-(o.y+.5)/grid.ny)*100" r="1.6" fill="#ffa15c" stroke="#fff2e6" stroke-width=".4"/></svg><div class="scene-note">{{fallback?'2D FALLBACK / NORTH UP':'NORTH −Z / EAST +X'}}<br><span>{{fallback?'Color encodes field value · select a cell':data.terrain&&(terrainEnabled||layer==='terrain')?'Height: relative terrain · color: selected field':'Height encodes field value · flat reference surface'}}</span></div><div v-if="view==='map'" class="cloud-key map-key"><span v-if="mapLayers.base!=='none'"><i :style="{background:mapLayers.base==='temperature'?'linear-gradient(90deg,hsl(223 55% 30%),hsl(11 55% 42%))':'linear-gradient(90deg,hsl(260 35% 26%),hsl(140 35% 44%))'}"></i>{{mapLayers.base==='temperature'?`Temperature ${(temperatureRange[0]-273.15).toFixed(0)}–${(temperatureRange[1]-273.15).toFixed(0)} °C`:`Pressure ${(pressureRange[0]/100).toFixed(0)}–${(pressureRange[1]/100).toFixed(0)} hPa`}}</span><span v-if="mapLayers.isobars">━ isobars {{mapLayers.isobarIntervalHpa}} hPa (bright = {{mapLayers.isobarIntervalHpa*2}} hPa)</span><template v-if="mapLayers.precipitation&&data.precipitation"><span v-for="r in [0.5,3,15,40]" :key="r"><i :style="{background:rateColor(r)}"></i>{{r}} mm/h</span></template><template v-if="mapLayers.clouds&&data.clouds"><span v-for="t in CLOUD_TYPES.slice(1)" :key="t.key"><i :style="{background:t.color}"></i>{{t.abbreviation}}</span></template><span v-if="mapLayers.fronts&&data.clouds"><i style="background:#4da3ff"></i>cold <i style="background:#ff6b6b"></i>warm <i style="background:#c792ea"></i>stationary</span><template v-if="(mapLayers.storms||mapLayers.stormWind)&&data.storms"><span v-for="c in CATEGORIES" :key="c.key"><i :style="{background:c.color}"></i>{{c.short}} {{c.label}}</span></template><span v-if="mapLayers.surge&&data.storms"><i style="background:#00e5ff"></i>storm surge</span><template v-if="mapLayers.tornado&&data.severe"><span><i style="background:#ffe066"></i>STP low <i style="background:#ff7f50"></i>moderate <i style="background:#c724b1"></i>significant</span></template><template v-if="data.orography"><span v-if="mapLayers.lifting"><i style="background:#3da5ff"></i>up-slope <i style="background:#ff8c42"></i>descent</span><span v-if="mapLayers.coldPools"><i style="background:#9ad7ff"></i>cold pool ❄</span><span v-if="mapLayers.foehn">F foehn</span><span v-if="mapLayers.blocking"><i style="background:#f0e68c"></i>blocked flow</span></template></div><div v-else-if="layer==='clouds'" class="cloud-key"><span v-for="t in CLOUD_TYPES" :key="t.key"><i :style="{background:t.color}"></i>{{t.abbreviation}} {{t.label}}</span></div><div v-else class="legend"><span>{{range[0].toFixed(1)}} {{unit}}</span><div :style="layer==='aspect'?{background:'linear-gradient(90deg,red,yellow,lime,cyan,blue,magenta,red)'}:['rainfall','water','soil'].includes(layer)?{background:'linear-gradient(90deg,#2675cc,#26ccb2)'}:{}"></div><span>{{range[1].toFixed(1)}} {{unit}}</span></div><div v-if="layer==='aspect'" class="aspect-key">0° N · 90° E · 180° S · 270° W · gray = flat</div><div class="gestures">{{fallback?'SELECT A CELL TO INSPECT':'DRAG TO ORBIT · SCROLL TO ZOOM · CLICK TO INSPECT'}}</div></div><div v-if="snapshots.length>1" class="timeline"><div class="playback"><button @click="seek(frameIndex-1)" :disabled="frameIndex===0" aria-label="Previous frame">‹</button><button @click="togglePlayback">{{playing?'Pause':'Play'}}</button><button @click="seek(frameIndex+1)" :disabled="frameIndex===snapshots.length-1" aria-label="Next frame">›</button><span>Frame {{frameIndex+1}} / {{snapshots.length}} · +{{forecast.elapsed_seconds/60}} min · {{rainfallPhase}}</span></div><input aria-label="Timeline frame" type="range" min="0" :max="snapshots.length-1" :value="frameIndex" @input="seek($event.target.value)"><p>{{data.orography?`Engine orography · ${data.orography.foehnCells} foehn cells · ${data.orography.poolCells} cold pools · surface ${(data.orography.tendency*3600).toFixed(2)} K/h`:data.storms?`${data.storms.synthetic?'Synthetic mock':'Engine'} storms · ${data.storms.list.length} active · events so far: ${visibleEvents.map(e=>e.kind).join(', ')||'none'}`+(data.severe?` · tornado possible in ${data.severe.possibleCells} cells`:''):data.precipitation?`${data.precipitation.synthetic?'Synthetic mock':'Engine'} outcomes · ${data.precipitation.precipitating} precipitating cells · ${data.precipitation.lightningCells} thunderstorms · ${data.precipitation.hailCells} hail · ${data.precipitation.snowCells} snow · max ${data.precipitation.maxRate.toFixed(1)} mm/h`:data.clouds?`${data.clouds.synthetic?'Synthetic mock':'Engine'} cloud snapshots · heating ${data.clouds.heating.toFixed(1)} K · ${data.clouds.cloudy} cloudy cells · ${data.clouds.storms} thunderstorm cells · ${data.clouds.fronts} frontal cells`:data.coupled?`Coupled engine snapshots · fixed color scale · pressure static · scalar stability number ${data.coupled.stability.toFixed(2)} · supersaturated cells ${data.coupled.supersaturated}`:data.atmosphere?'Synthetic regional snapshots · fixed color scale · no coupling to local engine physics':'Discrete solver snapshots · fixed color scale · rainfall accumulates from the start · unavailable at time zero'}}</p></div><p v-if="layer==='rainfall' && data.rain" class="rain-interval">Accumulation interval: {{data.rain.period_start_utc.replace('T',' ').replace('Z',' UTC')}} → {{data.rain.valid_time_utc.replace('T',' ').replace('Z',' UTC')}}</p><p v-if="['water','soil'].includes(layer) && data.surfaceWater" class="rain-interval">Surface {{data.surfaceWater.stored_volume_m3.toFixed(2)}} m³ · Soil {{data.surfaceWater.soil_volume_m3.toFixed(2)}} m³ · Rain input {{data.surfaceWater.cumulative_rainfall_volume_m3.toFixed(2)}} m³ · Evaporated {{data.surfaceWater.evaporated_volume_m3.toFixed(2)}} m³ · Drained {{data.surfaceWater.drained_volume_m3.toFixed(2)}} m³ · Discharged {{data.surfaceWater.discharged_volume_m3.toFixed(2)}} m³ · Balance error {{data.surfaceWater.balance_error_m3.toExponential(2)}} m³<br>{{data.surfaceWater.boundary==='configured_outlets'?'Configured surface outlets':'Closed boundaries'}} · unknown rainfall cells are impermeable masks · prototype routing<br>Step {{data.surfaceWater.parameters.timestep_seconds}} s · Infiltration {{(data.surfaceWater.parameters.infiltration_rate_m_s*3600000).toFixed(2)}} mm/h · Evaporation {{(data.surfaceWater.parameters.evaporation_rate_m_s*3600000).toFixed(2)}} mm/h · Drainage {{(data.surfaceWater.parameters.drainage_rate_m_s*3600000).toFixed(2)}} mm/h<span v-if="data.surfaceWater.soil_capacity_m!==null"> · soil capacity {{data.surfaceWater.soil_capacity_m*1000}} mm</span></p><section v-if="comparisonFrames" class="comparison"><div class="section-label">SCENARIO COMPARISON · SAME FORCING / TIME</div><div class="comparison-switch"><button @click="exportComparison">Export all frames (CSV)</button><button :class="{selected:comparisonView==='baseline'}" @click="comparisonView='baseline'">Show baseline</button><button :class="{selected:comparisonView==='variant'}" @click="comparisonView='variant'">Show {{comparisonName}}</button></div><p>Viewing {{comparisonView==='baseline'?'baseline':comparisonName}} · Δ = variant − baseline · volumes in m³</p><table><thead><tr><th>Metric</th><th>Baseline</th><th>{{comparisonName}}</th><th>Δ</th></tr></thead><tbody><tr v-for="row in comparisonRows" :key="row.label"><th>{{row.label}}</th><td>{{row.baseline.toFixed(2)}}</td><td>{{row.variant.toFixed(2)}}</td><td>{{row.delta>=0?'+':''}}{{row.delta.toFixed(2)}}</td></tr></tbody></table><div class="comparison-chart"><small>SURFACE STORAGE OVER TIME · full timeline, shared scale<br>Green = baseline · Blue = variant · dashed line = selected time</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Surface water volume comparison"><polyline :points="chartPath(snapshots)" fill="none" stroke="#b1d9a4" stroke-width=".6"/><polyline :points="chartPath(comparisonFrames)" fill="none" stroke="#75bbfa" stroke-width=".6"/><line :x1="frameIndex/(snapshots.length-1)*100" :x2="frameIndex/(snapshots.length-1)*100" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0 → {{snapshots.at(-1).forecast.elapsed_seconds/60}} minutes · 0–{{chartMaximum.toFixed(0)}} m³</small></div><p>Baseline infiltration {{(snapshots[0].surfaceWater.parameters.infiltration_rate_m_s*3600000).toFixed(2)}} mm/h · Variant {{(comparisonFrames[0].surfaceWater.parameters.infiltration_rate_m_s*3600000).toFixed(2)}} mm/h</p></section><section v-if="outletSeries.length" class="comparison outlet-report"><div class="section-label">SURFACE OUTLET DISCHARGE</div><p>Orange markers identify configured boundary outlets. Discharged water leaves the modeled domain and remains in the mass budget.</p><div class="outlet-charts"><div class="comparison-chart"><small>CUMULATIVE DISCHARGE · m³</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Cumulative outlet discharge"><polyline :points="outletPath('cumulative_m3',outletVolumeMax)" fill="none" stroke="#ffb77a" stroke-width=".7"/><line :x1="outletTimePosition" :x2="outletTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{outletVolumeMax.toFixed(1)}} m³ · 0–{{visibleFrames.at(-1).forecast.elapsed_seconds/60}} min</small></div><div class="comparison-chart"><small>INTERVAL-MEAN DISCHARGE · m³/s</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Interval mean outlet discharge"><polyline :points="outletPath('mean_rate_m3_s',outletRateMax)" fill="none" stroke="#75bbfa" stroke-width=".7"/><line :x1="outletTimePosition" :x2="outletTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{outletRateMax.toFixed(2)}} m³/s · averages between snapshots</small></div></div><p>Selected time: discharged {{outletSeries[frameIndex].cumulative_m3.toFixed(2)}} m³ · interval mean {{outletSeries[frameIndex].mean_rate_m3_s===null?'no preceding interval':outletSeries[frameIndex].mean_rate_m3_s.toFixed(3)+' m³/s'}}</p></section><div class="metrics extra-metrics"><div><small>DOMAIN AREA</small><strong>{{metrics.area_km2.toLocaleString()}} <em>km²</em></strong></div><div><small>TEMPERATURE MIN / MEAN / MAX</small><strong class="date">{{metrics.temperature_min_c.toFixed(1)}} / {{metrics.temperature_mean_c.toFixed(1)}} / {{metrics.temperature_max_c.toFixed(1)}} °C</strong></div><div><small>WIND MEAN / MAX</small><strong class="date">{{metrics.wind_mean_m_s.toFixed(1)}} / {{metrics.wind_max_m_s.toFixed(1)}} m/s</strong></div><template v-if="data.atmosphere"><div><small>MEAN CLOUD FRACTION</small><strong>{{metrics.cloud_pct.toFixed(1)}} <em>%</em></strong></div><div><small>PRESSURE MIN / MAX</small><strong class="date">{{metrics.pressure_min_hpa.toFixed(1)}} / {{metrics.pressure_max_hpa.toFixed(1)}} hPa</strong></div><div><small>MEAN RELATIVE HUMIDITY</small><strong>{{metrics.humidity_mean_pct.toFixed(1)}} <em>%</em></strong></div></template><template v-if="data.rain"><div><small>RAINFALL COVERAGE</small><strong>{{metrics.rain_coverage_pct.toFixed(1)}} <em>%</em></strong></div><div><small>MEAN RAIN · COVERED CELLS</small><strong>{{metrics.rain_mean_mm?.toFixed(2)??'Unknown'}} <em>mm</em></strong></div></template><template v-if="data.surfaceWater"><div><small>WET AREA · DEPTH &gt; 0.1 MM</small><strong>{{metrics.wet_area_km2.toFixed(2)}} <em>km²</em></strong></div><div><small>MAX SURFACE WATER</small><strong>{{metrics.water_max_mm?.toFixed(2)}} <em>mm</em></strong></div><div><small>MEAN SOIL CAPACITY USED</small><strong>{{metrics.soil_fill_pct?.toFixed(1)??'Unknown'}} <em>%</em></strong></div></template></div><div v-if="orographyMetrics" class="metrics extra-metrics"><div><small>FOEHN CELLS · MAX WARMING</small><strong class="date">{{orographyMetrics.foehn_cells}} · +{{orographyMetrics.max_foehn_warming_k.toFixed(1)}} K</strong></div><div><small>COLD POOLS · MAX DEFICIT</small><strong class="date">{{orographyMetrics.cold_pool_cells}} · −{{orographyMetrics.max_cold_pool_k.toFixed(1)}} K</strong></div><div><small>RISING / SINKING AIR</small><strong class="date">{{orographyMetrics.rising_pct.toFixed(0)}} % / {{orographyMetrics.sinking_pct.toFixed(0)}} %</strong></div><div><small>MAX BLOCKED · OROGRAPHIC RAIN</small><strong class="date">{{(orographyMetrics.max_blocked_fraction*100).toFixed(0)}} % · {{orographyMetrics.max_precipitation_rate.toFixed(1)}} mm/h</strong></div><div><small>RIDGE ORIENTATION</small><strong class="date">{{orographyMetrics.orientation_dominant_deg===null?'—':orographyMetrics.orientation_dominant_deg.toFixed(0)+'° (0 = N–S, 90 = E–W)'}}</strong></div><div><small>SURFACE TENDENCY</small><strong class="date">{{orographyMetrics.surface_tendency_k_h>=0?'+':''}}{{orographyMetrics.surface_tendency_k_h.toFixed(2)}} K/h {{orographyMetrics.surface_tendency_k_h<0?'(night)':orographyMetrics.surface_tendency_k_h>0?'(day)':''}}</strong></div></div><div v-if="hydrologyMetrics" class="metrics extra-metrics"><div><small>PEAK DISCHARGE · FLOODED AREA</small><strong class="date">{{hydrologyMetrics.max_discharge_m3_s.toFixed(1)}} m³/s · {{hydrologyMetrics.flooded_area_km2.toFixed(0)}} km²</strong></div><div><small>FLOOD CLASSES L / M / H / X</small><strong class="date">{{hydrologyMetrics.class_cells.low}} / {{hydrologyMetrics.class_cells.medium}} / {{hydrologyMetrics.class_cells.high}} / {{hydrologyMetrics.class_cells.extreme}}</strong></div><div><small>LANDSLIDES · DEBRIS</small><strong class="date">{{hydrologyMetrics.landslides_total}} ({{hydrologyMetrics.landslides_now}} now) · {{(hydrologyMetrics.landslide_volume_m3/1000).toFixed(0)}} ×10³ m³</strong></div><div><small>SEDIMENT YIELD · MAX EROSION</small><strong class="date">{{hydrologyMetrics.sediment_yield_t.toFixed(0)}} t · {{hydrologyMetrics.max_erosion_mm.toFixed(2)}} mm</strong></div><div><small>RAINING · SOIL SATURATION</small><strong class="date">{{hydrologyMetrics.raining_pct.toFixed(0)}} % · {{(hydrologyMetrics.mean_saturation*100).toFixed(0)}} %</strong></div><div><small>RUNOFF RATIO · WARNINGS</small><strong class="date">{{hydrologyMetrics.runoff_ratio===null?'—':(hydrologyMetrics.runoff_ratio*100).toFixed(0)+' %'}} · {{hydrologyMetrics.threshold_cells}} cells</strong></div><div><small>STORES · hm³ (snow / surface / soil / gw / rivers / lakes)</small><strong class="date">{{(hydrologyMetrics.storage.snow/1e6).toFixed(1)}} / {{(hydrologyMetrics.storage.surface/1e6).toFixed(1)}} / {{(hydrologyMetrics.storage.soil/1e6).toFixed(0)}} / {{(hydrologyMetrics.storage.groundwater/1e6).toFixed(0)}} / {{(hydrologyMetrics.storage.channels/1e6).toFixed(1)}} / {{(hydrologyMetrics.storage.lakes/1e6).toFixed(1)}}</strong></div><div><small>CUMULATIVE · hm³ (rain → sea / edge / ET)</small><strong class="date">{{(hydrologyMetrics.cumulative.precipitation/1e6).toFixed(1)}} → {{(hydrologyMetrics.cumulative.ocean_discharge/1e6).toFixed(1)}} / {{(hydrologyMetrics.cumulative.edge_outflow/1e6).toFixed(1)}} / {{(hydrologyMetrics.cumulative.evapotranspiration/1e6).toFixed(1)}}</strong></div><div><small>NETWORK</small><strong class="date">{{hydrologyMetrics.basins}} basins · {{hydrologyMetrics.lakes}} lakes · {{hydrologyMetrics.channel_km}} river cells</strong></div></div><section v-if="hydrograph.length" class="comparison outlet-report"><div class="section-label">HYDROGRAPH · {{chosen&&data.hydrology?.network.channel[chosen.i]?`SELECTED REACH (cell ${hydrographCell})`:`PEAK REACH (cell ${hydrographCell})`}}</div><p>Discharge at the reach over the run with the rainfall rate on the same cell. Click a river cell to move the gauge.</p><div class="outlet-charts"><div class="comparison-chart"><small>DISCHARGE · m³/s</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Discharge hydrograph"><polyline :points="hydrographPath('discharge_m3_s',hydrographMax)" fill="none" stroke="#75bbfa" stroke-width=".7"/><line :x1="hydrographTimePosition" :x2="hydrographTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{hydrographMax.toFixed(1)}} m³/s · 0–{{(visibleFrames.at(-1).forecast.elapsed_seconds/3600).toFixed(0)}} h</small></div><div class="comparison-chart"><small>RAINFALL · mm/h</small><svg viewBox="0 0 100 50" preserveAspectRatio="none" aria-label="Rainfall hyetograph"><polyline :points="hydrographPath('rain_mm_h',hydrographRainMax)" fill="none" stroke="#9fd0ff" stroke-width=".7"/><line :x1="hydrographTimePosition" :x2="hydrographTimePosition" y1="0" y2="50" stroke="#93a5af" stroke-dasharray="1 1" stroke-width=".3"/></svg><small>0–{{hydrographRainMax.toFixed(1)}} mm/h</small></div></div><p v-if="visibleLandslides.length">Landslides so far: <template v-for="(e,i) in visibleLandslides.slice(-6)" :key="i">{{i?' · ':''}}cell {{e.cell}} → {{e.deposited_in}} ({{(e.volume_m3/1000).toFixed(1)}} ×10³ m³, {{(e.runout_length_m/1000).toFixed(1)}} km)</template>{{visibleLandslides.length>6?` · … ${visibleLandslides.length} in total`:''}}</p></section><div v-if="stormMetrics" class="metrics extra-metrics"><div><small>TROPICAL CYCLONES</small><strong>{{stormMetrics.storm_count}} <em>({{stormMetrics.storms_over_land}} over land)</em></strong></div><div><small>STRONGEST</small><strong class="date">{{stormMetrics.strongest_wind_m_s.toFixed(1)}} m/s · {{categoryInfo(stormMetrics.strongest_category).label}}<template v-if="stormMetrics.lowest_pressure_hpa"> · {{stormMetrics.lowest_pressure_hpa.toFixed(0)}} hPa</template></strong></div><div><small>LANDFALLS / MERGERS / GENESES SO FAR</small><strong class="date">{{stormMetrics.landfalls_so_far}} / {{stormMetrics.mergers_so_far}} / {{stormMetrics.geneses_so_far}}</strong></div><div><small>MAX SURGE · MAX STORM WIND</small><strong class="date">{{stormMetrics.max_surge_m.toFixed(1)}} m · {{stormMetrics.max_storm_wind_m_s.toFixed(0)}} m/s</strong></div><div><small>POTENTIAL INTENSITY · GENESIS INDEX</small><strong class="date">{{stormMetrics.max_potential_intensity_m_s.toFixed(0)}} m/s · {{stormMetrics.max_genesis_index.toFixed(1)}}</strong></div><div v-if="severeMetrics"><small>TORNADO PARAMETER · POSSIBLE CELLS · CAP BROKEN</small><strong class="date">{{severeMetrics.max_stp.toFixed(2)}} · {{severeMetrics.tornado_possible_cells}} · {{severeMetrics.cap_broken_cells}} / {{severeMetrics.capped_cells}}</strong></div></div><div v-else-if="severeMetrics" class="metrics extra-metrics"><div><small>MAX TORNADO PARAMETER</small><strong>{{severeMetrics.max_stp.toFixed(2)}}</strong></div><div><small>TORNADO POSSIBLE CELLS</small><strong>{{severeMetrics.tornado_possible_cells}}</strong></div><div><small>CAP BROKEN / CAPPED CELLS</small><strong class="date">{{severeMetrics.cap_broken_cells}} / {{severeMetrics.capped_cells}}</strong></div><div><small>MAX HELICITY · LOW-LEVEL SHEAR</small><strong class="date">{{severeMetrics.max_helicity.toFixed(0)}} m²/s² · {{severeMetrics.max_low_level_shear.toFixed(1)}} m/s</strong></div><div><small>MAX HEATED CAPE</small><strong>{{severeMetrics.max_cape.toFixed(0)}} <em>J/kg</em></strong></div></div><div v-if="precipitationMetrics" class="metrics extra-metrics"><div><small>PRECIPITATING CELLS</small><strong>{{precipitationMetrics.precipitating_pct.toFixed(0)}} <em>%</em></strong></div><div><small>RATE MEAN (WET) / MAX</small><strong class="date">{{precipitationMetrics.mean_rate_mm_h.toFixed(1)}} / {{precipitationMetrics.max_rate_mm_h.toFixed(1)}} mm/h</strong></div><div><small>INTERVAL ACCUMULATION MEAN / MAX</small><strong class="date">{{precipitationMetrics.mean_accumulation_mm.toFixed(1)}} / {{precipitationMetrics.max_accumulation_mm.toFixed(1)}} mm</strong></div><div><small>THUNDERSTORM / HAIL / SNOW CELLS</small><strong class="date">{{precipitationMetrics.lightning_cells}} / {{precipitationMetrics.hail_cells}} / {{precipitationMetrics.snow_cells}}<template v-if="precipitationMetrics.max_hail_cm>0"> · hail ≤ {{precipitationMetrics.max_hail_cm.toFixed(1)}} cm</template></strong></div><div><small>HAZARDS</small><strong class="date">{{Object.entries(precipitationMetrics.hazard_counts).map(([h,n])=>`${HAZARD_LABELS[h]} ${n}`).join(' · ')||'none'}}</strong></div><div><small>PRECIPITABLE WATER (MEAN)</small><strong>{{precipitationMetrics.mean_precipitable_water_mm.toFixed(1)}} <em>mm</em></strong></div></div><div v-if="cloudMetrics" class="metrics extra-metrics"><div><small>CLOUD COVER / CLOUDY CELLS</small><strong class="date">{{cloudMetrics.cloud_cover_pct.toFixed(0)}} % / {{cloudMetrics.cloudy_pct.toFixed(0)}} %</strong></div><div><small>THUNDERSTORM CELLS</small><strong>{{cloudMetrics.thunderstorm_cells}}</strong></div><div><small>FRONTS COLD / WARM / STATIONARY</small><strong class="date">{{cloudMetrics.cold_front_cells}} / {{cloudMetrics.warm_front_cells}} / {{cloudMetrics.stationary_front_cells}} <em>cells</em></strong></div><div><small>DOMINANT CLOUD</small><strong class="date">{{cloudTypeInfo(cloudMetrics.dominant_type).label}}</strong></div><div><small>MEAN BASE / TOP</small><strong class="date">{{cloudMetrics.mean_base_m===null?'—':cloudMetrics.mean_base_m.toFixed(0)+' / '+cloudMetrics.mean_top_m.toFixed(0)+' m'}}</strong></div><div><small>FRONTAL / CONVECTIVE CELLS · HEATING</small><strong class="date">{{cloudMetrics.frontal_cells}} / {{cloudMetrics.convective_cells}} · {{cloudMetrics.surface_heating_k.toFixed(1)}} K</strong></div></div><div class="metrics"><div><small>GRID RESOLUTION</small><strong>{{grid.nx}} × {{grid.ny}} <em>cells</em></strong></div><div><small>CELL SPACING</small><strong>{{grid.spacing_east_m}} × {{grid.spacing_north_m}} <em>m</em></strong></div><div><small>VALID TIME</small><strong class="date">{{time}}</strong></div></div></article></main>
  <p v-if="error" class="error" role="alert">{{error}}</p><footer><span>TerraFlux Physics / Research viewer v0.1</span><span>{{snapshots.length>1?'Snapshot playback':'Single snapshot'}} · {{data.terrain?'Visual terrain':'Flat surface'}} · No live solver</span></footer>
